export type Recipient = {
  id: string
  name: string
  account: string
  currency: string
}

export const RECENT_RECIPIENTS: Recipient[] = [
  { id: "r1", name: "Amara Okafor", account: "•••• 4521", currency: "NGN" },
  { id: "r2", name: "Lukas Weber", account: "•••• 1187", currency: "EUR" },
  { id: "r3", name: "Priya Nair", account: "•••• 7734", currency: "INR" },
  { id: "r4", name: "Sofia Rossi", account: "•••• 2290", currency: "EUR" },
]

export const SEND_CURRENCY = "USD"
export const EXCHANGE_RATE = 0.92
export const FEE_FLAT = 3.99

export type SendMoneyData = {
  recipientId: string | null
  sendAmount: string
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipientId: null,
  sendAmount: "",
}

export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const

export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (p: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (i: number) => void
}

export function getRecipient(id: string | null): Recipient | undefined {
  return RECENT_RECIPIENTS.find((r) => r.id === id)
}

export function computeTotals(sendAmount: string) {
  const amount = parseFloat(sendAmount) || 0
  const fee = amount > 0 ? FEE_FLAT : 0
  const total = amount + fee
  const recipientGets = amount * EXCHANGE_RATE
  return { amount, fee, total, recipientGets }
}

