"use client"

import { useState } from "react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RECENT_RECIPIENTS } from "../schema"
import type { SendMoneyStepProps } from "../schema"
import { RecipientRow } from "./_parts"

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")

  const filtered = RECENT_RECIPIENTS.filter((r) =>
    r.name.toLowerCase().includes(query.trim().toLowerCase())
  )

  const select = (id: string) => {
    patch({ recipientId: id })
    next()
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <div>
        <Label htmlFor="recipient-search" size="sm">
          Search recipients
        </Label>
        <Input
          id="recipient-search"
          size="md"
          variant="default"
          placeholder="Search by name"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <span
          style={{
            fontSize: "var(--atlas-text-caption)",
            fontWeight: "var(--atlas-font-weight-medium)",
            color: "var(--atlas-foreground-muted)",
          }}
        >
          Recent recipients
        </span>
        {filtered.length === 0 && (
          <span
            style={{
              fontSize: "var(--atlas-text-body-sm)",
              color: "var(--atlas-foreground-muted)",
              paddingBlock: "var(--atlas-spacing-4)",
            }}
          >
            No recipients match &quot;{query}&quot;.
          </span>
        )}
        {filtered.map((r) => (
          <RecipientRow
            key={r.id}
            recipient={r}
            selected={data.recipientId === r.id}
            onSelect={() => select(r.id)}
          />
        ))}
      </div>
    </div>
  )
}

