"use client"

import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  CardFooter,
} from "@atlas/ui-web/compositions/Card/Card"
import {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from "@atlas/ui-web/compositions/Dialog/Dialog"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { mockSubmit } from "../../_shared/mockApi"
import { EXCHANGE_RATE, SEND_CURRENCY, computeTotals, getRecipient } from "../schema"
import type { SendMoneyStepProps } from "../schema"

export function Review({ data, back, reset }: SendMoneyStepProps & { reset?: () => void }) {
  const recipient = getRecipient(data.recipientId)
  const { amount, fee, total, recipientGets } = computeTotals(data.sendAmount)
  const [open, setOpen] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [sent, setSent] = useState(false)

  const confirm = async () => {
    setBusy(true)
    setError(null)
    try {
      await mockSubmit({ recipientId: data.recipientId, amount })
      setSent(true)
      setOpen(false)
    } catch (e) {
      setError((e as Error).message)
    } finally {
      setBusy(false)
    }
  }

  if (sent) {
    return (
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: "var(--atlas-spacing-4)",
          paddingInline: "var(--atlas-spacing-4)",
          paddingBlockStart: "var(--atlas-spacing-12)",
          textAlign: "center",
        }}
      >
        <div
          aria-hidden
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            inlineSize: "64px",
            blockSize: "64px",
            borderRadius: "var(--atlas-radius-full)",
            background: "var(--atlas-success-subtle)",
            color: "var(--atlas-success)",
            fontSize: "var(--atlas-font-size-2xl)",
            fontWeight: "var(--atlas-font-weight-bold)",
          }}
        >
          ✓
        </div>
        <h2
          style={{
            fontSize: "var(--atlas-text-h3)",
            fontWeight: "var(--atlas-font-weight-semibold)",
            color: "var(--atlas-foreground)",
            margin: 0,
          }}
        >
          Money on its way
        </h2>
        <p
          style={{
            fontSize: "var(--atlas-text-body-sm)",
            color: "var(--atlas-foreground-muted)",
            margin: 0,
          }}
        >
          {SEND_CURRENCY} {total.toFixed(2)} sent to {recipient?.name}.
        </p>
        {reset && (
          <Button variant="outline" size="lg" onClick={reset}>
            Send another
          </Button>
        )}
      </div>
    )
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <Card variant="outlined" size="md">
        <CardHeader>
          <CardTitle as="h3">Recipient</CardTitle>
        </CardHeader>
        <CardContent>
          <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
            <span style={{ fontSize: "var(--atlas-text-body)", color: "var(--atlas-foreground)" }}>
              {recipient?.name ?? "—"}
            </span>
            <span
              style={{
                fontSize: "var(--atlas-text-caption)",
                color: "var(--atlas-foreground-muted)",
              }}
            >
              {recipient?.account} · {recipient?.currency}
            </span>
          </div>
        </CardContent>
      </Card>

      <Card variant="outlined" size="md">
        <CardHeader>
          <CardTitle as="h3">Payment summary</CardTitle>
        </CardHeader>
        <CardContent>
          <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
            <SummaryRow label="You send" value={`${SEND_CURRENCY} ${amount.toFixed(2)}`} />
            <SummaryRow
              label="Recipient gets"
              value={`${recipient?.currency ?? ""} ${recipientGets.toFixed(2)}`}
            />
            <SummaryRow label="Fee" value={`${SEND_CURRENCY} ${fee.toFixed(2)}`} />
            <SummaryRow
              label="Exchange rate"
              value={`1 ${SEND_CURRENCY} = ${EXCHANGE_RATE} ${recipient?.currency ?? ""}`}
            />
          </div>
        </CardContent>
        <CardFooter justify="between">
          <span
            style={{
              fontSize: "var(--atlas-text-body)",
              fontWeight: "var(--atlas-font-weight-semibold)",
              color: "var(--atlas-foreground)",
            }}
          >
            Total
          </span>
          <span
            style={{
              fontSize: "var(--atlas-text-body)",
              fontWeight: "var(--atlas-font-weight-semibold)",
              color: "var(--atlas-foreground)",
            }}
          >
            {SEND_CURRENCY} {total.toFixed(2)}
          </span>
        </CardFooter>
      </Card>

      {error && <Alert variant="danger" title="Couldn't send" description={error} />}

      <div style={{ display: "flex", gap: "var(--atlas-spacing-3)" }}>
        <Button variant="outline" size="lg" onClick={back}>
          Back
        </Button>
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild>
            <Button variant="primary" size="lg" style={{ flex: 1 }}>
              Confirm and send
            </Button>
          </DialogTrigger>
          <DialogContent size="sm">
            <DialogHeader>
              <DialogTitle>Send {SEND_CURRENCY} {total.toFixed(2)}?</DialogTitle>
              <DialogDescription>
                {recipient?.name} will receive {recipient?.currency} {recipientGets.toFixed(2)}.
                This can&apos;t be undone once sent.
              </DialogDescription>
            </DialogHeader>
            <DialogFooter justify="end">
              <DialogClose asChild>
                <Button variant="outline" size="md" disabled={busy}>
                  Cancel
                </Button>
              </DialogClose>
              <Button variant="primary" size="md" loading={busy} onClick={confirm}>
                Confirm and send
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  )
}

function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between" }}>
      <span
        style={{
          fontSize: "var(--atlas-text-body-sm)",
          color: "var(--atlas-foreground-muted)",
        }}
      >
        {label}
      </span>
      <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground)" }}>
        {value}
      </span>
    </div>
  )
}

