"use client"

import type { KeyboardEvent } from "react"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import type { Recipient } from "../schema"

function initials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase()
}

export function RecipientRow({
  recipient,
  selected,
  onSelect,
}: {
  recipient: Recipient
  selected?: boolean
  onSelect: () => void
}) {
  return (
    <div
      role="button"
      tabIndex={0}
      aria-pressed={!!selected}
      onKeyDown={(e: KeyboardEvent) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault()
          onSelect()
        }
      }}
    >
    <Card variant="outlined" size="sm" interactive selected={selected} onClick={onSelect}>
      <CardContent>
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
          <div
            aria-hidden
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              inlineSize: "40px",
              blockSize: "40px",
              borderRadius: "var(--atlas-radius-full)",
              background: "var(--atlas-primary-subtle)",
              color: "var(--atlas-primary)",
              fontSize: "var(--atlas-font-size-sm)",
              fontWeight: "var(--atlas-font-weight-semibold)",
              flexShrink: 0,
            }}
          >
            {initials(recipient.name)}
          </div>
          <div style={{ display: "flex", flexDirection: "column", flex: 1, minInlineSize: 0 }}>
            <span
              style={{
                fontSize: "var(--atlas-text-body)",
                fontWeight: "var(--atlas-font-weight-medium)",
                color: "var(--atlas-foreground)",
              }}
            >
              {recipient.name}
            </span>
            <span
              style={{
                fontSize: "var(--atlas-text-caption)",
                color: "var(--atlas-foreground-muted)",
              }}
            >
              {recipient.account}
            </span>
          </div>
          <Badge variant="secondary" size="sm">
            {recipient.currency}
          </Badge>
        </div>
      </CardContent>
    </Card>
  )
}
